fn main() {
    // `app/build.sh` writes the real notices (tools/notices.py); a plain
    // `cargo build` from a fresh clone gets a placeholder so it still builds.
    let notices = std::path::Path::new("THIRD_PARTY_NOTICES.txt");
    if !notices.exists() {
        std::fs::write(
            notices,
            "Third-party notices are generated by tools/notices.py (run app/build.sh).\n",
        )
        .expect("write THIRD_PARTY_NOTICES.txt");
    }
    tauri_build::build()
}
